import assert from 'node:assert/strict';
import { collectFusionProposals, normalizeFusionConfig } from '/work/worker/fusion.ts';
const cleanup = Promise.withResolvers();
const retained = [];
let cancelled = 0;
const response = new Response(new ReadableStream({ cancel() { cancelled++; return cleanup.promise; } }), { status: 503 });
const config = normalizeFusionConfig({ adviserModels: ['local/rejected'] });
try {
  const result = await collectFusionProposals(config, { messages: [] }, async () => response, work => {
    const entry = { settled: false, work };
    retained.push(entry);
    void work.then(() => { entry.settled = true; }, () => { entry.settled = true; });
  });
  await new Promise(resolve => setImmediate(resolve));
  assert.deepEqual(result.failedModels, ['local/rejected']);
  assert.equal(cancelled, 1);
  assert.ok(retained.some(entry => !entry.settled), 'HTTP-error cancellation must remain retained after collection returns');
} finally {
  cleanup.resolve();
  await Promise.allSettled(retained.map(entry => entry.work));
}
